#!/usr/bin/env python3
"""news-image-20261121 entry: write the day's news image to /output.

The image is a newspaper front page ("THE WORLD") summing up the
world news of Saturday 21 November 2026: Russian missiles landing
in Poland, Wall Street sliding into correction, the Claude / Riemann
Hypothesis proof claim, COP31 running into overtime in Antalya,
Saudi Arabia intercepting three Houthi missiles, Cyclone Akvan
crossing Odisha, KL Rahul's century in Wellington, and India's NSE
becoming the world's fifth-largest listed exchange. It was drawn
with PIL by the build script (build.py) kept beside this file, and
embedded here as base64 so this program needs no network and no
other file.

Standard library only. Reads MAKEFUN_OUTPUT_DIR (default /output)
and writes entry.png there. Deterministic: the same bytes every run.
"""

import base64
import os
import sys

# The winning image (variant v1, newspaper front page), 1024x1024 PNG.
_IMAGE_B64 = ""


def main() -> int:
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(_IMAGE_B64)
    # Sanity check: the embedded bytes must be a whole PNG image.
    if not data.startswith(b"\x89PNG\r\n\x1a\n"):
        raise ValueError("embedded image is not a PNG")
    path = os.path.join(out_dir, "entry.png")
    with open(path, "wb") as fh:
        fh.write(data)
    return 0


if __name__ == "__main__":
    sys.exit(main())
